import http.server, socketserver, sys, json, threading
class H(http.server.BaseHTTPRequestHandler):
    protocol_version="HTTP/1.1"
    def log_message(self,*a): pass
    def do_GET(self):
        hdrs = {k:v for k,v in self.headers.items()}
        body = json.dumps({"path":self.path,"headers":hdrs,"method":"GET"}).encode()
        if self.path=="/404":
            self.send_response(404); self.send_header("Content-Length",str(len(body))); self.send_header("Content-Type","application/json"); self.end_headers(); self.wfile.write(body); return
        if self.path=="/notjson":
